import React from 'react';
import '../styles/programs.css';

function Programs() {
  return (
    <div className="programs">
      <h2>Our Programs</h2>
      <ul>
        <li><strong>Health & Wellness</strong> – SDG 3 focus on Mental Health, Teen Fathers, Drug Abuse, and Primary Health Care.</li>
        <li><strong>Education & Research</strong> – SDG 4 focus with vocational training and school support.</li>
        <li><strong>Governance & Leadership</strong> – SDG 16 focus with civic education and strategic leadership.</li>
        <li><strong>Environment</strong> – SDG 13 focus with climate change awareness.</li>
        <li><strong>Economic Strengthening</strong> – SDG 8 focus with innovation and vocational skills.</li>
      </ul>
    </div>
  );
}

export default Programs;
